(()=>{'use strict';
// Rounded internally consistent formation/combustion data, OpenStax Appendix G.
const S={C:{label:'C(s, graphite)',c:1,h:0,f:0,b:-393.5},H2:{label:'H₂(g)',c:0,h:2,f:0,b:-285.8},CH4:{label:'CH₄(g)',c:1,h:4,f:-74.6,b:-890.5},C2H4:{label:'C₂H₄(g)',c:2,h:4,f:52.4,b:-1411},C2H6:{label:'C₂H₆(g)',c:2,h:6,f:-84,b:-1560.4},C2H2:{label:'C₂H₂(g)',c:2,h:2,f:227.4,b:-1300.2}};
const bank=[{name:'Formation of methane',left:{C:1,H2:2},right:{CH4:1}},{name:'Hydrogenation of ethene',left:{C2H4:1,H2:1},right:{C2H6:1}},{name:'Partial hydrogenation of ethyne',left:{C2H2:1,H2:1},right:{C2H4:1}},{name:'Hydrogenation of ethyne',left:{C2H2:1,H2:2},right:{C2H6:1}},{name:'Formation of ethane',left:{C:2,H2:3},right:{C2H6:1}}];
const n=x=>Number(x.toFixed(4)).toString(),signed=x=>(x<0?'−':'+')+Math.abs(x).toFixed(1),term=(q,s)=>(q===1?'':n(q)+' ')+s,mix=x=>Object.entries(x).map(([s,q])=>term(q,S[s].label)).join(' + ');
function totals(p){return Object.entries(p.left).reduce((a,[s,q])=>({c:a.c+S[s].c*q,h:a.h+S[s].h*q}),{c:0,h:0});}
function sum(mixture,mode){return Object.entries(mixture).reduce((a,[s,q])=>a+S[s][mode==='combustion'?'b':'f']*q,0);}
function targetH(p){return sum(p.right,'formation')-sum(p.left,'formation');}
function expectedBottom(p,mode){const t=totals(p);return{a:t.c,b:t.h/(mode==='combustion'?2:2)};}
function arrowH(mixture,mode,direction){const natural=mode==='combustion'?'down':'up';return sum(mixture,mode)*(direction===natural?1:-1);}
function validate(p,mode,bottom,dirs,assignments){const expected=expectedBottom(p,mode),errors=[];if(bottom.kind!==mode||Math.abs(bottom.a-expected.a)>1e-8||Math.abs(bottom.b-expected.b)>1e-8)errors.push('bottom');for(let side=0;side<2;side++){if(!dirs[side])errors.push('direction-'+side);const wanted=side?p.right:p.left,got=assignments[side];if([...new Set([...Object.keys(wanted),...Object.keys(got)])].some(s=>Math.abs((wanted[s]||0)-(got[s]||0))>1e-8))errors.push('cards-'+side);}return errors;}
if(typeof module!=='undefined'&&module.exports)module.exports={S,bank,totals,sum,targetH,expectedBottom,arrowH,validate};if(typeof document==='undefined')return;
const $=id=>document.getElementById('hc-'+id);if(!$('game'))return;let mode='combustion',index=Math.floor(Math.random()*bank.length),p=bank[index],dirs=['',''],assignments=[{},{}],selected=null,start=null,traced=false;
function bottom(){return{kind:$('bottom-kind').value,a:Number($('bottom-a').value),b:Number($('bottom-b').value)}}
function bottomText(){const b=bottom();return b.kind==='combustion'?term(b.a,'CO₂(g)')+' + '+term(b.b,'H₂O(l)'):term(b.a,'C(s, graphite)')+' + '+term(b.b,'H₂(g)');}
function invalidate(){traced=false;$('motion').innerHTML='';$('result').hidden=true;$('feedback').textContent='';$('answer').value='';['bottom','cards-0','cards-1','direction-0','direction-1'].forEach(id=>$(id).classList.remove('hc-error'));}
function cardText(s){return S[s].label+' · ΔH°'+(mode==='combustion'?'c':'f')+' = '+signed(S[s][mode==='combustion'?'b':'f'])+' kJ mol⁻¹';}
function renderBank(){const keys=[...new Set([...Object.keys(p.left),...Object.keys(p.right)])];const extra=Object.keys(S).find(s=>!keys.includes(s));if(extra)keys.push(extra);$('bank').innerHTML=keys.map(s=>`<button type="button" draggable="true" data-card="${s}" aria-pressed="${selected===s}">${cardText(s)}</button>`).join('');}
function renderAssignments(side){$('cards-'+side).innerHTML=Object.keys(assignments[side]).map(s=>`<div class="hc-assigned"><span>${S[s].label}</span><label>× <input data-scale="${s}" type="number" min="0.25" max="8" step="0.25" value="${assignments[side][s]}" aria-label="Amount of ${S[s].label} on ${side?'right':'left'} arrow"></label><button type="button" data-remove="${s}" aria-label="Remove ${S[s].label}">×</button></div>`).join('')||'<span class="hc-empty">No enthalpy cards assigned</span>';}
function draw(){const t=totals(p),oxygen=t.c+t.h/4,add=mode==='combustion'?' + '+term(oxygen,'O₂(g)'):'',v=[mix(p.left)+add,mix(p.right)+add,bottomText()];$('left').textContent=v[0];$('right').textContent=v[1];$('bottom-label').textContent=v[2];$('left').setAttribute('aria-pressed',start===0);$('right').setAttribute('aria-pressed',start===1);$('bottom-node').setAttribute('aria-pressed',start===2);for(let side=0;side<2;side++){const down=dirs[side]==='down',up=dirs[side]==='up',path=$('arrow-'+side);path.setAttribute('marker-end',down?'url(#hc-arrowhead)':'');path.setAttribute('marker-start',up?'url(#hc-arrowhead-start)':'');path.style.strokeDasharray=dirs[side]?'':'6 5';$('arrow-value-'+side).textContent=dirs[side]?'ΔH° = '+signed(arrowH(assignments[side],mode,dirs[side]))+' kJ':'Choose direction';$('direction-'+side).textContent=dirs[side]?(down?'↓ To bottom':'↑ From bottom'):'Set arrow direction';$('direction-'+side).setAttribute('aria-label',(side?'Right':'Left')+' arrow: '+(dirs[side]||'unset'));}}
function newProblem(change){if(change)index=(index+1+Math.floor(Math.random()*(bank.length-1)))%bank.length;p=bank[index];dirs=['',''];assignments=[{},{}];selected=null;start=null;invalidate();$('title').textContent=p.name;$('target').textContent=mix(p.left)+' → '+mix(p.right);$('bottom-kind').value=mode;$('bottom-a').value=1;$('bottom-b').value=1;$('combustion').setAttribute('aria-pressed',mode==='combustion');$('formation').setAttribute('aria-pressed',mode==='formation');$('oxygen-note').hidden=mode!=='combustion';$('zero-note').hidden=mode!=='formation';document.dispatchEvent(new Event('chemi-controls-sync'));renderBank();renderAssignments(0);renderAssignments(1);draw();}
function add(side,s=selected){if(!s||!S[s]){$('feedback').textContent='Select an enthalpy card first, then add it to an arrow.';return;}assignments[side][s]=(assignments[side][s]||0)+1;invalidate();renderAssignments(side);draw();}
$('bank').addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(!b)return;selected=b.dataset.card;renderBank()});$('bank').addEventListener('dragstart',e=>{const b=e.target.closest('[data-card]');if(!b)return;selected=b.dataset.card;e.dataTransfer.setData('text/plain',selected);e.dataTransfer.effectAllowed='copy'});
for(let side=0;side<2;side++){const box=$('side-'+side);box.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy'});box.addEventListener('drop',e=>{e.preventDefault();const s=e.dataTransfer.getData('text/plain');if(S[s])add(side,s)});$('add-'+side).addEventListener('click',()=>add(side));$('direction-'+side).addEventListener('click',()=>{dirs[side]=dirs[side]==='down'?'up':'down';invalidate();draw()});$('cards-'+side).addEventListener('change',e=>{const s=e.target.dataset.scale;if(!s)return;const value=Number(e.target.value);if(!Number.isFinite(value)||value<.25||value>8){e.target.value=assignments[side][s];$('feedback').textContent='Choose an amount between 0.25 and 8.';return;}assignments[side][s]=value;invalidate();draw()});$('cards-'+side).addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;delete assignments[side][b.dataset.remove];invalidate();renderAssignments(side);draw()});}
[0,1,2].forEach(node=>$(node===0?'left':node===1?'right':'bottom-node').addEventListener('click',()=>{if(start===null){start=node;$('feedback').textContent='Choose the endpoint of this arrow.';}else if(start===node){start=null;$('feedback').textContent='';}else if(start!==2&&node!==2){$('feedback').textContent='Connect each top box to the bottom box.';start=null;}else{const side=start===2?node:start;dirs[side]=start===2?'up':'down';start=null;invalidate();}draw()}));
for(const id of ['bottom-kind','bottom-a','bottom-b'])$(id).addEventListener('change',()=>{invalidate();draw()});
$('trace').addEventListener('click',()=>{invalidate();const b=bottom(),errors=validate(p,mode,b,dirs,assignments);if(!Number.isFinite(b.a)||!Number.isFinite(b.b)||b.a<=0||b.b<=0){$('feedback').textContent='Enter positive coefficients for both bottom substances.';return;}if(errors.length){errors.forEach(id=>$(id).classList.add('hc-error'));$('feedback').textContent=errors.includes('bottom')?'Check the bottom substances and coefficients against the total C and H atoms.':errors.some(x=>x.startsWith('direction'))?'Set both arrow directions by selecting their start and end boxes.':'Check the highlighted arrow’s cards and amounts. Use the substances on that side, including any elements with zero formation enthalpy.';return;}traced=true;$('result').hidden=false;const l=arrowH(assignments[0],mode,dirs[0]),r=arrowH(assignments[1],mode,dirs[1]),ls=dirs[0]==='down'?1:-1,rs=dirs[1]==='up'?1:-1;$('expression').textContent='ΔH°target = '+(ls===1?'':'−')+'('+signed(l)+') '+(rs===1?'+':'−')+' ('+signed(r)+') kJ';$('route-note').textContent='Reactants → bottom → products. Left arrow: '+(ls===1?'follow':'reverse')+'; right arrow: '+(rs===1?'follow':'reverse')+'.';$('cycle-view').scrollIntoView({behavior:'smooth',block:'center'});$('motion').innerHTML='<circle r="8" fill="#c09940"><animateMotion dur="2s" fill="freeze" path="M 175 105 L 350 300 L 525 105" /></circle>';});
$('check').addEventListener('click',()=>{if(!traced)return;const raw=$('answer').value.trim(),v=Number(raw);$('feedback').textContent=!raw||!Number.isFinite(v)?'Enter the target enthalpy, including its sign.':Math.abs(v-targetH(p))<.051?'Correct. ΔH° = '+signed(targetH(p))+' kJ for the target reaction as written.':'Check the route signs: reverse the sign when travelling against an arrow.';});$('answer').addEventListener('keydown',e=>{if(e.key==='Enter')$('check').click()});$('next').addEventListener('click',()=>newProblem(true));$('reset').addEventListener('click',()=>newProblem(false));for(const value of ['combustion','formation'])$(value).addEventListener('click',()=>{mode=value;newProblem(false)});newProblem(false);
})();
